method isSublist(sub: seq<int>, main: seq<int>) returns (result: bool)
  ensures result <==> OccursFrom(sub, main, 0)
{
  var i := 0;
  while i + |sub| <= |main|
    invariant OccursFrom(sub, main, 0) <==> OccursFrom(sub, main, i)
    decreases |main| + 1 - i
  {
    var j := 0;
    while j < |sub| && sub[j] == main[i + j]
      invariant 0 <= j <= |sub|
      invariant MatchesFrom(sub, main, i, 0) <==> MatchesFrom(sub, main, i, j)
    {
      j := j + 1;
    }
    if j == |sub| {
      result := true;
      return;
    }
    i := i + 1;
  }
  result := false;
}

