import icontract
from typing import List


@icontract.ensure(lambda sub, main, result: result == any(
    main[i:i + len(sub)] == sub for i in range(len(main) - len(sub) + 1)))
def isSublist(sub: List[int], main: List[int]) -> bool:
    n, m = len(sub), len(main)
    i = 0
    while i + n <= m:
        if main[i:i + n] == sub:
            return True
        i += 1
    return False
